-- SQLite schema for Phase 1: source dataset, regional filter, simulated telemetry.
-- Foreign keys are enforced per connection (PRAGMA foreign_keys = ON in data_engineering.db).
-- Provenance:
--   source_records      -> 'dataset'   (rows exactly as downloaded; note the Kaggle dataset
--                                       itself describes its rows as engineered synthetic data)
--   telemetry_readings  -> 'synthetic' (generated by this project's simulator)

-- Downloaded files that were loaded, with checksums for change detection.
CREATE TABLE IF NOT EXISTS source_files (
    source_file         TEXT PRIMARY KEY,
    dataset_slug        TEXT NOT NULL,
    sha256              TEXT NOT NULL CHECK (length(sha256) = 64),
    size_bytes          INTEGER NOT NULL CHECK (size_bytes >= 0),
    row_count           INTEGER NOT NULL CHECK (row_count >= 0),
    column_count        INTEGER NOT NULL CHECK (column_count > 0),
    source_description  TEXT,
    loaded_at           TEXT NOT NULL
);

-- Original dataset rows. The source has no row or equipment identifier, so identity is
-- (file, 1-based data row number). All 35 source columns are kept with their source types.
CREATE TABLE IF NOT EXISTS source_records (
    source_file                 TEXT NOT NULL REFERENCES source_files(source_file),
    source_row_number           INTEGER NOT NULL CHECK (source_row_number >= 1),
    provenance                  TEXT NOT NULL DEFAULT 'dataset' CHECK (provenance = 'dataset'),
    server_type                 TEXT,
    cooling_type                TEXT,
    datacenter_region           TEXT,
    time_of_day                 TEXT,
    maintenance_status          TEXT,
    energy_source_primary       TEXT,
    server_age_years            INTEGER,
    rack_u_position             INTEGER,
    workload_intensity          REAL,
    cpu_utilization             REAL,
    gpu_utilization             REAL,
    memory_utilization          REAL,
    storage_utilization         REAL,
    disk_io_iops                REAL,
    network_throughput_gbps     REAL,
    network_latency_ms          REAL,
    virtual_machines_count      INTEGER,
    ambient_temperature_c       REAL,
    humidity_percentage         REAL,
    inlet_temperature_c         REAL,
    exhaust_temperature_c       REAL,
    fan_speed_rpm               REAL,
    airflow_cfm                 REAL,
    cooling_efficiency          REAL,
    power_supply_efficiency     REAL,
    ups_battery_health          REAL,
    power_consumption_kw        REAL,
    pue                         REAL,
    wue                         REAL,
    carbon_intensity_gco2_kwh   REAL,
    renewable_energy_ratio      REAL,
    carbon_emission_kg          REAL,
    compute_cost_usd            REAL,
    energy_efficiency_class     TEXT,
    failure_risk_level          TEXT,
    PRIMARY KEY (source_file, source_row_number)
);
CREATE INDEX IF NOT EXISTS idx_source_records_region ON source_records (datacenter_region);

-- Membership of source rows in a named filter (e.g. 'datacenter_region=NA').
-- Stores keys only; the full rows stay in source_records.
CREATE TABLE IF NOT EXISTS region_filtered_records (
    filter_name         TEXT NOT NULL,
    source_file         TEXT NOT NULL,
    source_row_number   INTEGER NOT NULL,
    PRIMARY KEY (filter_name, source_file, source_row_number),
    FOREIGN KEY (source_file, source_row_number)
        REFERENCES source_records (source_file, source_row_number)
);

CREATE VIEW IF NOT EXISTS filtered_source_records AS
SELECT f.filter_name, s.*
FROM region_filtered_records AS f
JOIN source_records AS s USING (source_file, source_row_number);

-- One row per simulation run. run_id is derived from the config + source checksum,
-- so rerunning the same configuration replaces the same run instead of duplicating it.
CREATE TABLE IF NOT EXISTS simulation_runs (
    run_id              TEXT PRIMARY KEY,
    generator_name      TEXT NOT NULL,
    generator_version   TEXT NOT NULL,
    seed                INTEGER NOT NULL,
    start_ts_utc        TEXT NOT NULL,
    duration_minutes    INTEGER NOT NULL CHECK (duration_minutes > 0),
    frequency_seconds   INTEGER NOT NULL CHECK (frequency_seconds > 0),
    expected_slots      INTEGER NOT NULL CHECK (expected_slots > 0),
    asset_count         INTEGER NOT NULL CHECK (asset_count > 0),
    missing_rate        REAL NOT NULL CHECK (missing_rate >= 0 AND missing_rate < 1),
    region_filter       TEXT NOT NULL,
    source_file         TEXT NOT NULL REFERENCES source_files(source_file),
    source_sha256       TEXT NOT NULL,
    config_json         TEXT NOT NULL,
    content_sha256      TEXT NOT NULL,
    created_at          TEXT NOT NULL
);

-- Simulated assets. The source has no equipment identifiers, so every asset_id here is a
-- simulation construct (identifier_origin = 'synthetic'). Static attributes are copied from
-- the source row used as that asset's baseline.
CREATE TABLE IF NOT EXISTS asset_metadata (
    run_id                      TEXT NOT NULL REFERENCES simulation_runs(run_id) ON DELETE CASCADE,
    asset_id                    TEXT NOT NULL,
    identifier_origin           TEXT NOT NULL CHECK (identifier_origin IN ('source', 'synthetic')),
    baseline_source_file        TEXT NOT NULL,
    baseline_source_row_number  INTEGER NOT NULL,
    server_type                 TEXT NOT NULL,
    cooling_type                TEXT,
    datacenter_region           TEXT NOT NULL,
    energy_source_primary       TEXT,
    maintenance_status          TEXT,
    server_age_years            INTEGER,
    rack_u_position             INTEGER,
    energy_efficiency_class     TEXT,
    failure_risk_level          TEXT,
    PRIMARY KEY (run_id, asset_id),
    FOREIGN KEY (baseline_source_file, baseline_source_row_number)
        REFERENCES source_records (source_file, source_row_number)
);

-- The full expected time grid: exactly one row per (run, asset, slot), whether or not a
-- reading was observed. Missing readings have is_missing = 1 and NULL metrics (never 0).
CREATE TABLE IF NOT EXISTS telemetry_readings (
    run_id                  TEXT NOT NULL,
    asset_id                TEXT NOT NULL,
    ts_utc                  TEXT NOT NULL CHECK (
        ts_utc GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z'),
    slot_index              INTEGER NOT NULL CHECK (slot_index >= 0),
    provenance              TEXT NOT NULL DEFAULT 'synthetic' CHECK (provenance = 'synthetic'),
    is_missing              INTEGER NOT NULL CHECK (is_missing IN (0, 1)),
    is_anomalous            INTEGER NOT NULL DEFAULT 0 CHECK (is_anomalous IN (0, 1)),
    workload_intensity      REAL,
    cpu_utilization         REAL,
    gpu_utilization         REAL,
    memory_utilization      REAL,
    storage_utilization     REAL,
    disk_io_iops            REAL,
    network_throughput_gbps REAL,
    network_latency_ms      REAL,
    ambient_temperature_c   REAL,
    humidity_percentage     REAL,
    inlet_temperature_c     REAL,
    exhaust_temperature_c   REAL,
    fan_speed_rpm           REAL,
    airflow_cfm             REAL,
    power_consumption_kw    REAL,
    pue                     REAL,
    -- A missing slot carries no values; an observed slot carries all of them.
    CHECK (is_missing = 0 OR coalesce(
        workload_intensity, cpu_utilization, gpu_utilization, memory_utilization,
        storage_utilization, disk_io_iops, network_throughput_gbps, network_latency_ms,
        ambient_temperature_c, humidity_percentage, inlet_temperature_c, exhaust_temperature_c,
        fan_speed_rpm, airflow_cfm, power_consumption_kw, pue) IS NULL),
    CHECK (is_missing = 1 OR (
        workload_intensity IS NOT NULL AND cpu_utilization IS NOT NULL AND gpu_utilization IS NOT NULL
        AND memory_utilization IS NOT NULL AND storage_utilization IS NOT NULL
        AND disk_io_iops IS NOT NULL AND network_throughput_gbps IS NOT NULL
        AND network_latency_ms IS NOT NULL AND ambient_temperature_c IS NOT NULL
        AND humidity_percentage IS NOT NULL AND inlet_temperature_c IS NOT NULL
        AND exhaust_temperature_c IS NOT NULL AND fan_speed_rpm IS NOT NULL
        AND airflow_cfm IS NOT NULL AND power_consumption_kw IS NOT NULL AND pue IS NOT NULL)),
    CHECK (is_missing = 0 OR is_anomalous = 0),
    PRIMARY KEY (run_id, asset_id, ts_utc),
    UNIQUE (run_id, asset_id, slot_index),
    FOREIGN KEY (run_id, asset_id) REFERENCES asset_metadata (run_id, asset_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_telemetry_run_ts ON telemetry_readings (run_id, ts_utc);

-- Injected anomalies (ground truth for evaluating detection later).
CREATE TABLE IF NOT EXISTS anomaly_events (
    anomaly_id          TEXT PRIMARY KEY,
    run_id              TEXT NOT NULL,
    asset_id            TEXT NOT NULL,
    anomaly_type        TEXT NOT NULL,
    metrics_json        TEXT NOT NULL,
    shape               TEXT NOT NULL CHECK (shape IN ('step', 'ramp')),
    magnitude_std       REAL NOT NULL CHECK (magnitude_std > 0),
    start_slot          INTEGER NOT NULL CHECK (start_slot >= 0),
    end_slot            INTEGER NOT NULL CHECK (end_slot >= start_slot),
    start_ts_utc        TEXT NOT NULL,
    end_ts_utc          TEXT NOT NULL,
    FOREIGN KEY (run_id, asset_id) REFERENCES asset_metadata (run_id, asset_id) ON DELETE CASCADE
);

-- One row per (anomaly, slot, metric) where an injected value replaced the clean baseline.
-- clean_value keeps the un-perturbed value for evaluation.
CREATE TABLE IF NOT EXISTS anomaly_labels (
    anomaly_id      TEXT NOT NULL REFERENCES anomaly_events(anomaly_id) ON DELETE CASCADE,
    run_id          TEXT NOT NULL,
    asset_id        TEXT NOT NULL,
    ts_utc          TEXT NOT NULL,
    metric          TEXT NOT NULL,
    clean_value     REAL NOT NULL,
    injected_value  REAL NOT NULL,
    PRIMARY KEY (anomaly_id, ts_utc, metric),
    FOREIGN KEY (run_id, asset_id, ts_utc)
        REFERENCES telemetry_readings (run_id, asset_id, ts_utc) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_anomaly_labels_reading ON anomaly_labels (run_id, asset_id, ts_utc);
